<?php

namespace Modules\Auth\Controllers;

use Illuminate\Http\Request;
use Illuminate\Routing\Controller;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;
use Illuminate\Support\Facades\Storage;

/**
 * The authenticated user's OWN profile photo, for every role. The user is
 * always taken from the JWT (auth_user.sub) — never from request input — so a
 * user can only read, replace or remove their own photo.
 *
 * Files live on the "public" disk under profile_photos/ with a random name
 * generated by Laravel; only that relative path is stored in
 * users.profile_photo_path.
 */
class ProfilePhotoController extends Controller
{
    private const DIRECTORY = 'profile_photos';

    private function currentUserId(Request $request): ?int
    {
        $authUser = $request->input('auth_user');
        $id = $authUser['sub'] ?? ($authUser['id'] ?? null);
        return $id ? (int) $id : null;
    }

    /** Clear error instead of a SQL failure while the migration hasn't been run. */
    private function columnMissingResponse()
    {
        return response()->json([
            'error' => 'Profile photos are not available yet: the database migration adding users.profile_photo_path has not been run.',
        ], 503);
    }

    public function show(Request $request)
    {
        $userId = $this->currentUserId($request);
        if (!$userId) {
            return response()->json(['error' => 'Unauthorized'], 401);
        }
        if (!Schema::hasColumn('users', 'profile_photo_path')) {
            return $this->columnMissingResponse();
        }

        $user = DB::table('users')->where('id', $userId)->first();
        $path = $user ? ($user->profile_photo_path ?: (isset($user->avatar) ? $user->avatar : null)) : null;

        return response()->json(['profile_photo_path' => $path]);
    }

    public function store(Request $request)
    {
        $userId = $this->currentUserId($request);
        if (!$userId) {
            return response()->json(['error' => 'Unauthorized'], 401);
        }
        if (!Schema::hasColumn('users', 'profile_photo_path')) {
            return $this->columnMissingResponse();
        }

        $photoUrl = $request->input('photo_url') ?? $request->input('url');
        $hasFile = $request->hasFile('photo');

        if (!$hasFile && (empty($photoUrl) || !is_string($photoUrl))) {
            return response()->json([
                'error' => 'Please choose an image file to upload or enter an image link URL.',
            ], 422);
        }

        if ($hasFile) {
            // mimes is checked against the file's detected content type, not just
            // its extension. SVG is deliberately not allowed (it can carry script).
            $request->validate([
                'photo' => 'required|file|mimes:jpg,jpeg,png,webp|max:2048',
            ], [
                'photo.required' => 'Please choose an image to upload.',
                'photo.uploaded' => 'The image could not be uploaded. It may be larger than 2 MB.',
                'photo.mimes' => 'The photo must be a JPG, PNG or WebP image.',
                'photo.max' => 'The photo must not be larger than 2 MB.',
            ]);

            $newPath = $request->file('photo')->store(self::DIRECTORY, 'public');
            if (!$newPath) {
                return response()->json(['error' => 'The photo could not be saved. Please try again.'], 500);
            }
        } else {
            $cleanUrl = trim((string) $photoUrl);
            if (!filter_var($cleanUrl, FILTER_VALIDATE_URL) && !str_starts_with($cleanUrl, 'data:image/')) {
                return response()->json(['error' => 'Please enter a valid HTTP, HTTPS, or image URL link.'], 422);
            }
            $newPath = $cleanUrl;
        }

        $user = DB::table('users')->where('id', $userId)->first();
        if (!$user) {
            return response()->json(['error' => 'User not found'], 404);
        }

        $updates = [
            'profile_photo_path' => $newPath,
            'updated_at' => now(),
        ];
        if (Schema::hasColumn('users', 'avatar')) {
            $updates['avatar'] = $newPath;
        }

        DB::table('users')->where('id', $userId)->update($updates);

        if ($user->profile_photo_path && $user->profile_photo_path !== $newPath) {
            $this->deleteStoredPhoto($user->profile_photo_path);
        }

        return response()->json([
            'message' => 'Profile photo updated.',
            'profile_photo_path' => $newPath,
        ]);
    }

    public function destroy(Request $request)
    {
        $userId = $this->currentUserId($request);
        if (!$userId) {
            return response()->json(['error' => 'Unauthorized'], 401);
        }
        if (!Schema::hasColumn('users', 'profile_photo_path')) {
            return $this->columnMissingResponse();
        }

        $user = DB::table('users')->where('id', $userId)->first();
        $oldPath = $user ? ($user->profile_photo_path ?: ($user->avatar ?? null)) : null;

        $updates = [
            'profile_photo_path' => null,
            'updated_at' => now(),
        ];
        if (Schema::hasColumn('users', 'avatar')) {
            $updates['avatar'] = null;
        }

        DB::table('users')->where('id', $userId)->update($updates);

        if ($oldPath) {
            $this->deleteStoredPhoto($oldPath);
        }

        return response()->json([
            'message' => 'Profile photo removed.',
            'profile_photo_path' => null,
            'avatar' => null,
        ]);
    }

    /** Only ever deletes files inside profile_photos/ on the public disk. */
    private function deleteStoredPhoto(?string $path): void
    {
        if ($path && str_starts_with($path, self::DIRECTORY . '/') && !str_contains($path, '..')) {
            Storage::disk('public')->delete($path);
        }
    }
}
